  if(a==='wgVwar'&&warVassalGoalTerms(s.vtype,x))s.war=x;
  if(a==='wgGo'){this.warDeclarationPreview(s.id,s.key,s.key==='fetih'?{targets:s.targets.slice()}:{vtype:s.vtype,war:s.war});return;}
